	{
		Interlocked.Increment(ref FilterPreRun);
		foreach (ITrigger trigger3 in Triggers)
		{
			if (trigger3.CheckProperty(proName))
			{
				trigger3.ReOnTrigger();
			}
		}
		foreach (ITrigger trigger4 in Triggers)
